/**
 * APK Download Bridge & Interceptor
 *
 * Solves the issue where Android WebViews cannot download or preview Blob/data URLs
 * generated by client-side libraries (jsPDF, SheetJS/XLSX, backup exports).
 *
 * When running inside the Android APK (where window.AndroidBridge is present):
 * 1. Intercepts synthetic <a download="..."> clicks and converts Blobs to Base64.
 * 2. Intercepts window.open(blobUrl, '_blank') calls (used by PDF previews).
 * 3. Sends the file to native AndroidBridge.saveBase64File() which saves the file to
 *    the device's public Downloads folder and triggers the native Android file viewer/share intent.
 *
 * In regular desktop/mobile browsers, native browser behavior is preserved without changes.
 */

const blobRegistry = new Map();
let isInterceptorInitialized = false;

export const isApkEnvironment = () => {
    return typeof window !== 'undefined' &&
        !!(window.AndroidBridge && typeof window.AndroidBridge.saveBase64File === 'function');
};

/**
 * Converts a Blob or File to a Base64 data URL string.
 */
export const blobToBase64 = (blob) => {
    return new Promise((resolve, reject) => {
        if (!blob) return resolve('');
        const reader = new FileReader();
        reader.onloadend = () => {
            resolve(reader.result || '');
        };
        reader.onerror = (err) => {
            reject(err);
        };
        reader.readAsDataURL(blob);
    });
};

/**
 * Programmatic helper to download a file in either APK or standard browser.
 */
export const downloadFile = async (data, fileName = 'download', mimeType = '') => {
    const name = fileName || 'download';

    if (isApkEnvironment()) {
        try {
            let base64 = null;
            let resolvedMime = mimeType;

            if (typeof data === 'string') {
                if (data.startsWith('data:')) {
                    base64 = data;
                } else if (data.startsWith('blob:')) {
                    const entry = blobRegistry.get(data);
                    const b = entry ? entry.blob : await fetch(data).then(r => r.blob());
                    if (!resolvedMime && b?.type) resolvedMime = b.type;
                    base64 = await blobToBase64(b);
                } else {
                    const encoded = btoa(unescape(encodeURIComponent(data)));
                    base64 = `data:${resolvedMime || 'text/plain'};base64,${encoded}`;
                }
            } else if (data instanceof Blob) {
                if (!resolvedMime && data.type) resolvedMime = data.type;
                base64 = await blobToBase64(data);
            } else if (data instanceof ArrayBuffer || ArrayBuffer.isView(data)) {
                const b = new Blob([data], { type: resolvedMime || 'application/octet-stream' });
                base64 = await blobToBase64(b);
            }

            if (base64) {
                window.AndroidBridge.saveBase64File(base64, name, resolvedMime || '');
                return true;
            }
        } catch (err) {
            console.error('[APK Download] Failed to save file via AndroidBridge:', err);
        }
    }

    // Default Browser Fallback
    let url = null;
    let shouldRevoke = false;

    if (typeof data === 'string' && (data.startsWith('blob:') || data.startsWith('data:'))) {
        url = data;
    } else if (data instanceof Blob) {
        url = URL.createObjectURL(data);
        shouldRevoke = true;
    }

    if (url) {
        const a = document.createElement('a');
        a.href = url;
        a.download = name;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        if (shouldRevoke) {
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        }
    }
    return true;
};

/**
 * Installs global interceptors for URL.createObjectURL, HTMLAnchorElement.prototype.click,
 * and window.open to transparently redirect all blob downloads through AndroidBridge in the APK.
 */
export const initApkDownloadInterceptor = () => {
    if (typeof window === 'undefined' || isInterceptorInitialized) return;
    isInterceptorInitialized = true;

    // 1. Intercept URL.createObjectURL to register Blobs in memory
    const originalCreateObjectURL = URL.createObjectURL;
    URL.createObjectURL = function (blob) {
        const url = originalCreateObjectURL.call(URL, blob);
        if (blob instanceof Blob && typeof url === 'string') {
            blobRegistry.set(url, {
                blob,
                type: blob.type || '',
                timestamp: Date.now()
            });

            // Keep cache bounded to 60 items
            if (blobRegistry.size > 60) {
                const oldest = blobRegistry.keys().next().value;
                blobRegistry.delete(oldest);
            }
        }
        return url;
    };

    // 2. Intercept URL.revokeObjectURL to keep registry tidy
    const originalRevokeObjectURL = URL.revokeObjectURL;
    URL.revokeObjectURL = function (url) {
        // Keep in registry briefly (10 seconds) so async download handlers have time to read it
        setTimeout(() => {
            blobRegistry.delete(url);
        }, 10000);
        return originalRevokeObjectURL.call(URL, url);
    };

    // 3. Intercept window.open(blobUrl, '_blank') (used by all PDF preview/print actions)
    const originalWindowOpen = window.open;
    window.open = function (url, target, features) {
        if (isApkEnvironment() && typeof url === 'string' && (url.startsWith('blob:') || url.startsWith('data:'))) {
            const entry = blobRegistry.get(url);
            const isPdf = (entry?.type && entry.type.includes('pdf')) || url.includes('application/pdf');
            const defaultName = isPdf
                ? `Report_${new Date().toISOString().split('T')[0]}.pdf`
                : `Document_${new Date().toISOString().split('T')[0]}`;

            (async () => {
                try {
                    let base64;
                    let mime = entry?.type || '';
                    if (url.startsWith('data:')) {
                        base64 = url;
                    } else {
                        const b = entry ? entry.blob : await fetch(url).then(r => r.blob());
                        if (!mime && b?.type) mime = b.type;
                        base64 = await blobToBase64(b);
                    }
                    if (isPdf && !mime) mime = 'application/pdf';
                    window.AndroidBridge.saveBase64File(base64, defaultName, mime);
                } catch (err) {
                    console.error('[APK window.open interceptor error]', err);
                }
            })();

            return null; // Prevent blank WebView popup window in Android
        }
        return originalWindowOpen.call(window, url, target, features);
    };

    // 4. Intercept <a download="..."> clicks (used by XLSX.writeFile, doc.save, and custom blob anchors)
    const originalAnchorClick = HTMLAnchorElement.prototype.click;
    HTMLAnchorElement.prototype.click = function () {
        if (isApkEnvironment()) {
            const href = this.getAttribute('href') || this.href;
            const downloadAttr = this.getAttribute('download') || this.download;

            if (downloadAttr || (href && (href.startsWith('blob:') || href.startsWith('data:')))) {
                if (href && (href.startsWith('blob:') || href.startsWith('data:'))) {
                    const entry = blobRegistry.get(href);
                    let resolvedName = downloadAttr;
                    if (!resolvedName) {
                        const isExcel = entry?.type?.includes('spreadsheet') || entry?.type?.includes('excel');
                        const isPdf = entry?.type?.includes('pdf');
                        if (isExcel) {
                            resolvedName = `Report_${new Date().toISOString().split('T')[0]}.xlsx`;
                        } else if (isPdf) {
                            resolvedName = `Report_${new Date().toISOString().split('T')[0]}.pdf`;
                        } else {
                            resolvedName = `Document_${new Date().toISOString().split('T')[0]}`;
                        }
                    }

                    (async () => {
                        try {
                            let base64;
                            let mime = entry?.type || '';
                            if (href.startsWith('data:')) {
                                base64 = href;
                            } else {
                                const b = entry ? entry.blob : await fetch(href).then(r => r.blob());
                                if (!mime && b?.type) mime = b.type;
                                base64 = await blobToBase64(b);
                            }
                            window.AndroidBridge.saveBase64File(base64, resolvedName, mime);
                        } catch (err) {
                            console.error('[APK a.click interceptor error]', err);
                        }
                    })();

                    return; // Prevent WebView default no-op behavior
                }
            }
        }
        return originalAnchorClick.call(this);
    };
};
